from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import product, combinations


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source, target = data["source"], data["target"]
    initial_mask = required_bit.get(source, 0)
    edges = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        edges[edge["u"]].append(edge)

    start = data["start"]
    initial = (source, initial_mask, 0)
    distances = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if (node == target and mask == full and
                (coupon_rule != "exact" or used == data["coupons"])):
            return {"arrival": time}

        for edge in edges[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            next_mask = mask | required_bit.get(edge["v"], 0)
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_used))
    return {"arrival": None}


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        tax = _round(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    rows_by_name = {}
    for name in names:
        rows = {row["version"]: row for row in packages[name]}
        rows_by_name[name] = rows
        versions = sorted(v for v in rows
                          if v not in blocked.get(name, []) and
                          (name not in pins or v == pins[name]))
        choices.append([-1] + versions)

    for vector in product(*choices):
        selected = {name: version for name, version in zip(names, vector)
                    if version != -1}
        adjacency = {name: [] for name in selected}
        valid = True

        for name, bounds in data["roots"].items():
            version = selected.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        for name, version in selected.items():
            row = rows_by_name[name][version]
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                other_version = selected.get(other)
                if (other_version is None or
                        not dep["min"] <= other_version <= dep["max"]):
                    valid = False
                    break
                adjacency[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be exactly the active closure of the roots.
        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(adjacency.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()

        def acyclic(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not acyclic(other) for other in adjacency[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(acyclic(name) for name in selected):
            continue
        return {"versions": selected}
    return {"error": "unsatisfiable"}


def _intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}):
        return {"error": "impossible"}
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for chosen in combinations(jobs, data["k"]):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["end"] > ordered[i + 1]["start"]
               for i in range(len(ordered) - 1)):
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


SOLVERS = {
    "component_01": lambda data: _route(data, "at_most", 1),
    "component_02": lambda data: _route(data, "exact", 1),
    "component_03": lambda data: _route(data, "at_most", 2),
    "component_04": lambda data: _route(data, "exact", 2),
    "component_05": lambda data: _route(data, "at_most", 1),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _intervals,
}
